import * as T from '../vendor/three.module.js';
import {textured} from './world.js';
export class Cockpit{
 constructor(aspect){this.scene=new T.Scene();this.camera=new T.PerspectiveCamera(58,aspect,.01,40);this.root=new T.Group();this.scene.add(this.root);this.needles=[];this.pods=[];
 this.m={wood:textured(0x392013,25),brass:new T.MeshStandardMaterial({color:0xb08748,roughness:.35,metalness:.78}),edge:new T.MeshStandardMaterial({color:0x5c4225,roughness:.43,metalness:.8}),black:new T.MeshStandardMaterial({color:0x101615,roughness:.48,metalness:.35}),ivory:new T.MeshStandardMaterial({color:0xf1d69b,roughness:.7,emissive:0x77501b,emissiveIntensity:.35}),lamp:new T.MeshBasicMaterial({color:0xffcc78}),steel:new T.MeshStandardMaterial({color:0x34413e,metalness:.8,roughness:.4})};
 const amb=new T.HemisphereLight(0xe4dbc2,0x1b140d,2.2);this.scene.add(amb);const warm=new T.PointLight(0xffb54e,25,12,2);warm.position.set(-1.5,.1,-1);this.scene.add(warm);const cool=new T.DirectionalLight(0xc1d6d1,1.4);cool.position.set(2,3,1);this.scene.add(cool);
 this.build();this.batchMoving();this.batchStatic();this.root.position.z=-1.05;}
 mesh(geo,mat,pos,parent=this.root,rot=null){let m=new T.Mesh(geo,this.m[mat]||mat);m.position.set(...pos);if(rot)m.rotation.set(...rot);parent.add(m);return m;}
 box(mat,x,y,z,w,h,d,parent=this.root,rot=null){return this.mesh(new T.BoxGeometry(w,h,d),mat,[x,y,z],parent,rot)}
 cyl(mat,x,y,z,rt,rb,h,parent=this.root,rot=null,n=32){return this.mesh(new T.CylinderGeometry(rt,rb,h,n),mat,[x,y,z],parent,rot)}
 torus(mat,x,y,z,rad,tube,parent=this.root,rot=null){return this.mesh(new T.TorusGeometry(rad,tube,8,48),mat,[x,y,z],parent,rot)}
 bolt(x,y,z,parent=this.root){this.cyl('edge',x,y,z,.019,.019,.012,parent,[Math.PI/2,0,0],6);this.box('black',x,y,z+.008,.021,.003,.003,parent)}
 plate(text,x,y,z,w=.4,h=.09,parent=this.root){let canvas=document.createElement('canvas');canvas.width=512;canvas.height=128;let c=canvas.getContext('2d');c.fillStyle='#a88a50';c.fillRect(0,0,512,128);c.strokeStyle='#352c1c';c.lineWidth=6;c.strokeRect(8,8,496,112);c.fillStyle='#29291d';c.font='bold 32px Georgia';c.textAlign='center';c.textBaseline='middle';c.fillText(text,256,66);let tex=new T.CanvasTexture(canvas);tex.colorSpace=T.SRGBColorSpace;this.mesh(new T.PlaneGeometry(w,h),new T.MeshStandardMaterial({map:tex,metalness:.5,roughness:.5}),[x,y,z],parent);}
 gauge(x,y,z,rad,label,max=100){let group=new T.Group();group.position.set(x,y,z);this.root.add(group);
 this.cyl('black',0,0,-.03,rad*1.13,rad*1.13,.11,group,[Math.PI/2,0,0]);this.torus('brass',0,0,.03,rad*1.04,rad*.075,group);this.torus('edge',0,0,.045,rad*.94,rad*.025,group);
 let canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;let c=canvas.getContext('2d');let gr=c.createRadialGradient(256,210,50,256,256,260);gr.addColorStop(0,'#e4ce9d');gr.addColorStop(1,'#b38b4b');c.fillStyle=gr;c.fillRect(0,0,512,512);c.translate(256,256);for(let i=0;i<=50;i++){let a=(i/50*1.5+.75)*Math.PI;c.save();c.rotate(a);c.strokeStyle='#3c3526';c.lineWidth=i%5===0?4:2;c.beginPath();c.moveTo(0,-218);c.lineTo(0,i%5===0?-192:-204);c.stroke();c.restore();if(i%10===0){c.fillStyle='#3b3221';c.font='28px Georgia';c.textAlign='center';c.textBaseline='middle';c.fillText(Math.round(i/50*max),Math.sin(a)*165,-Math.cos(a)*165);}}
 c.font='18px Georgia';c.textAlign='center';c.fillText(label,0,80);c.font='12px Georgia';c.fillText('KESTREL • CO.',0,105);let tex=new T.CanvasTexture(canvas);tex.colorSpace=T.SRGBColorSpace;this.mesh(new T.CircleGeometry(rad,48),new T.MeshStandardMaterial({map:tex,roughness:.6,emissive:0xb5752c,emissiveIntensity:.15}),[0,0,.031],group);
 let needle=new T.Group();needle.position.z=.043;needle.userData.dynamic=true;this.box('black',0,rad*.31,0,rad*.035,rad*1.15,.009,needle);this.cyl('brass',0,0,.008,rad*.09,rad*.09,.02,needle,[Math.PI/2,0,0]);group.add(needle);this.needles.push(needle);
 for(let i=0;i<4;i++){let a=i*Math.PI/2+Math.PI/4;this.bolt(Math.sin(a)*rad*1.22,Math.cos(a)*rad*1.22,.028,group);}return group;}
 build(){
 // Deep mahogany bridge console, inlaid panels and individually modeled brass fasteners.
 this.box('wood',0,-1.03,-1.84,4.65,.64,1.35,this.root,[-.14,0,0]);this.box('edge',0,-.7,-1.45,4.7,.055,.07);this.box('black',0,-1.35,-1.18,4.9,.22,.15);
 for(let x of [-1.75,-.8,.7,1.65]){this.box('edge',x,-.92,-1.145,.014,.45,.012);for(let yy of [-1.1,-.78])this.bolt(x,yy,-1.11);}
 for(let x=-2.1;x<=2.1;x+=.27){this.bolt(x,-.73,-1.115);this.bolt(x,-1.25,-1.115);}
 this.gauge(-1.26,-.94,-1.08,.21,'KNOTS',120);this.gauge(.92,-.95,-1.08,.19,'LIFT',400);this.gauge(1.46,-.93,-1.09,.115,'HULL',100);this.gauge(-.73,-.89,-1.08,.1,'STEAM',60);
 this.plate('AIRSHIP CONTROL PANEL',.05,-1.19,-1.08,.5,.075);this.plate('BALLAST RELEASE',.93,-1.2,-1.08,.33,.06);
 // Central control stick: turned metal plinth, twelve black grip ribs, crowned thumb cap.
 this.stick=new T.Group();this.stick.position.set(-.16,-1.02,-.98);this.stick.userData.dynamic=true;this.root.add(this.stick);
 this.cyl('edge',0,0,0,.2,.25,.06,this.stick);this.cyl('brass',0,.045,0,.14,.19,.06,this.stick);this.cyl('brass',0,.16,0,.065,.13,.17,this.stick);this.cyl('black',0,.42,0,.085,.07,.44,this.stick);
 for(let k=0;k<12;k++)this.torus('black',0,.22+k*.034,0,.083,.013,this.stick,[Math.PI/2,0,0]);this.cyl('brass',0,.65,0,.087,.087,.035,this.stick);this.cyl('edge',0,.67,0,.07,.086,.012,this.stick);
 for(let i=0;i<8;i++){let a=i/8*Math.PI*2;this.cyl('edge',Math.sin(a)*.21,.036,Math.cos(a)*.21,.017,.017,.014,this.stick,null,6);}
 // Lever quadrants with brass curved track and pivoting black handles.
 for(let side of [-1,1]){let xx=side<0?-1.93:.4;this.box('edge',xx,-.93,-1.05,.19,.47,.035);this.box('black',xx,-.93,-1.02,.09,.39,.018);let g=new T.Group();g.position.set(xx,-1.07,-.99);g.userData.dynamic=true;this.root.add(g);this.cyl('brass',0,.16,0,.017,.017,.32,g);this.mesh(new T.SphereGeometry(.048,14,10),'black',[0,.33,0],g);if(side<0)this.throttle=g;else this.lift=g;}
 // Four valve buttons and a pressure light bank.
 for(let k=0;k<4;k++){this.cyl('brass',-.54+k*.21,-.68,-1.38,.048,.055,.065);this.cyl(k===0?'lamp':'black',-.54+k*.21,-.64,-1.38,.033,.033,.013);}
 // Spoked wheel at the starboard bulkhead.
 this.wheel=new T.Group();this.wheel.position.set(1.99,-.89,-1.05);this.wheel.userData.dynamic=true;this.root.add(this.wheel);this.torus('brass',0,0,0,.31,.034,this.wheel);this.torus('edge',0,0,0,.276,.012,this.wheel);this.cyl('brass',0,0,0,.065,.065,.1,this.wheel,[Math.PI/2,0,0]);for(let k=0;k<8;k++){let a=k*Math.PI/4;this.box('brass',Math.sin(a)*.14,Math.cos(a)*.14,0,.022,.28,.026,this.wheel,[0,0,-a]);}
 // Broad divided windscreen: arches, heavy pillars, overhead plating, hand-drilled rivets.
 for(let side of [-1,1]){this.box('black',side*2.55,.65,-2.25,.16,3.9,.2,this.root,[0,0,side*.1]);this.box('edge',side*2.49,.65,-2.13,.026,3.8,.035,this.root,[0,0,side*.1]);this.box('black',side*1.08,.98,-2.72,.065,3,.08,this.root,[0,0,-side*.07]);this.box('edge',side*1.06,.98,-2.67,.013,3,.03,this.root,[0,0,-side*.07]);for(let j=0;j<11;j++)this.bolt(side*2.5,-.64+j*.27,-2.12);
 // Warm caged bridge lamps.
 this.cyl('edge',side*2.16,-.39,-1.9,.12,.16,.1);this.mesh(new T.SphereGeometry(.105,16,12),'lamp',[side*2.16,-.28,-1.9]);this.cyl('edge',side*2.16,-.16,-1.9,.12,.06,.04);for(let k=0;k<4;k++){let a=k*Math.PI/2;this.cyl('brass',side*2.16+Math.sin(a)*.11,-.27,-1.9+Math.cos(a)*.11,.009,.009,.22);}
 // Raised outer cannon barrels, with muzzle rings. Additional barrels show siege growth.
 let cannon=new T.Group();cannon.position.set(side*1.55,-.63,-3.2);cannon.userData.dynamic=true;this.root.add(cannon);this.cyl('black',0,0,0,.11,.15,1.5,cannon,[Math.PI/2,0,0]);for(let z of [-.66,-.4,.2])this.torus('brass',0,0,z,.12,.022,cannon);this.box('steel',0,-.14,.3,.36,.14,.5,cannon);this.pods.push(cannon);
 }
 this.box('black',0,2.05,-2.5,5.8,.23,.25);this.box('edge',0,1.92,-2.39,5.8,.025,.04);this.box('wood',0,2.28,-1.7,6,.25,2);
 // Hanging directional brass compass.
 this.cyl('brass',0,1.7,-2.45,.012,.012,.44);this.torus('edge',0,1.43,-2.45,.15,.018);this.plate('N     W     S',0,1.43,-2.43,.27,.07);
 this.extra=new T.Group();this.extra.userData.dynamic=true;this.root.add(this.extra);
 }
 batchMoving(){let movers=[];this.root.traverse(o=>{if(o.userData.dynamic)movers.push(o)});for(let group of movers){group.updateMatrixWorld(true);let inv=group.matrixWorld.clone().invert(),byMat=new Map(),old=[];group.traverse(o=>{if(!o.isMesh)return;let geo=o.geometry.clone().toNonIndexed();geo.applyMatrix4(inv.clone().multiply(o.matrixWorld));let arr=byMat.get(o.material)||[];arr.push(geo);byMat.set(o.material,arr);old.push(o);});old.forEach(o=>o.removeFromParent());for(let [mat,geos]of byMat){let g=new T.BufferGeometry();for(let a of ['position','normal','uv']){let len=geos.reduce((n,geo)=>n+geo.getAttribute(a).array.length,0),data=new Float32Array(len),off=0;for(let geo of geos){data.set(geo.getAttribute(a).array,off);off+=geo.getAttribute(a).array.length;}g.setAttribute(a,new T.BufferAttribute(data,a==='uv'?2:3));}group.add(new T.Mesh(g,mat));geos.forEach(g=>g.dispose());}} }
 batchStatic(){this.root.updateMatrixWorld(true);let groups=new Map(),remove=[];this.root.traverse(o=>{if(!o.isMesh)return;let p=o;while(p&&p!==this.root){if(p.userData.dynamic)return;p=p.parent;}let mat=o.material;let arr=groups.get(mat)||[];let geo=o.geometry.clone().toNonIndexed();geo.applyMatrix4(o.matrixWorld);arr.push(geo);groups.set(mat,arr);remove.push(o);});for(let obj of remove)obj.removeFromParent();for(let [mat,geos]of groups){let merged=new T.BufferGeometry();for(let attr of ['position','normal','uv']){let total=geos.reduce((n,g)=>n+(g.getAttribute(attr)?.array.length||0),0),data=new Float32Array(total),offset=0;for(let g of geos){let at=g.getAttribute(attr);if(at){data.set(at.array,offset);offset+=at.array.length;}}merged.setAttribute(attr,new T.BufferAttribute(data,attr==='uv'?2:3));}let mesh=new T.Mesh(merged,mat);this.root.add(mesh);geos.forEach(g=>g.dispose());}}
 upgrade(tiers){this.extra.clear();let [siege,,,eng,armor]=tiers;for(let side of [-1,1]){if(siege>=2){this.cyl('black',side*1.25,-.59,-3.25,.1+siege*.008,.13,1.5,this.extra,[Math.PI/2,0,0]);this.torus('brass',side*1.25,-.59,-4,.12,.025,this.extra);}for(let k=0;k<Math.floor(eng/2);k++){this.cyl('brass',side*(2.05+k*.14),-.78,-3.6,.13,.22,.8,this.extra,[Math.PI/2,0,0]);this.cyl('lamp',side*(2.05+k*.14),-.78,-3.18,.07,.07,.025,this.extra,[Math.PI/2,0,0]);}for(let k=0;k<Math.floor(armor/2);k++)this.box('brass',side*(.6+k*.24),-.64,-1.53,.12,.04,.2,this.extra);}}
 update(s,dt){let t=s.time;this.stick.rotation.z=T.MathUtils.damp(this.stick.rotation.z,-s.turn*.22,8,dt);this.stick.rotation.x=T.MathUtils.damp(this.stick.rotation.x,s.climb*.15,8,dt);this.throttle.rotation.x=-.4+s.speed*.012;this.lift.rotation.x=s.climb*.3;this.wheel.rotation.z=-s.yaw*2;this.needles[0].rotation.z=2.3-s.speed/80*4.6;this.needles[1].rotation.z=2.3-s.pos.y/400*4.6;this.needles[2].rotation.z=2.3-s.hull/100*4.6;this.needles[3].rotation.z=Math.sin(t*1.3)*.08-.4;this.root.position.y=.15+Math.sin(t*6)*.0015+s.kick*.018;this.root.rotation.z=-s.turn*.012;this.pods.forEach(p=>p.position.z=-3.2+s.kick*.15);}
 resize(a){this.camera.aspect=a;this.camera.updateProjectionMatrix();}
}
